const routes=[{name:"Maharashtra Splendor",origin:"Mumbai",destination:"Mumbai",importantStations:["Nashik","Aurangabad (Ellora)","Ajanta","Kolhapur","Goa","Sindhudurg"],duration:"7 Nights / 8 Days"},{name:"Indian Odyssey",origin:"New Delhi",destination:"Mumbai",importantStations:["Sawai Madhopur","Agra","Jaipur","Udaipur","Vadodara","Ellora Caves"],duration:"7 Nights / 8 Days"},{name:"Hidden Treasures of Gujarat",origin:"Mumbai",destination:"Mumbai",importantStations:["Vadodara","Palitana","Sasan Gir","Somnath","Little Rann of Kutch","Modhera","Patan"],duration:"7 Nights / 8 Days"},{name:"Indian Sojourn",origin:"Mumbai",destination:"New Delhi",importantStations:["Vadodara","Udaipur","Jodhpur","Agra","Sawai Madhopur","Jaipur"],duration:"7 Nights / 8 Days"}],destinations=[{region:"Aurangabad",attraction:"Ajanta & Ellora Caves",description:"UNESCO World Heritage sites featuring ancient rock-cut caves and stunning sculptures."},{region:"Kolhapur",attraction:"Mahalaxmi Temple & New Palace",description:"Experience the martial arts, local culture, and the grand architecture of the Marathas."},{region:"Goa",attraction:"Churches and Beaches",description:"A blend of Portuguese heritage, old churches in Old Goa, and scenic coastal beauty."},{region:"Nashik",attraction:"Vineyards and Godavari Ghats",description:"Known as the wine capital of India, combined with rich religious significance."},{region:"Sindhudurg",attraction:"Sindhudurg Fort",description:"A historical sea fort built by Chhatrapati Shivaji Maharaj."}];function renderRoutes(){const a=document.getElementById("routes-container");a&&(a.innerHTML=routes.map(a=>`\n    <div class="route-card">\n      <div>\n        <div style="color: var(--deccan-gold); font-size: 1.3rem; margin-bottom: 5px;"><strong>${a.name}</strong></div>\n        <div class="origin-dest">${a.origin} <i class="fa-solid fa-arrows-left-right" style="color: var(--text-muted); margin: 0 10px; font-size: 0.9rem;"></i> ${a.destination}</div>\n        <div class="stations"><strong>Via:</strong> ${a.importantStations.join(", ")}</div>\n      </div>\n      <div style="text-align: right;">\n        <span style="background: var(--deccan-purple); color: #fff; padding: 5px 10px; border-radius: 4px; font-size: 0.9rem; font-weight: bold;">\n          <i class="fa-regular fa-clock"></i> ${a.duration}\n        </span>\n      </div>\n    </div>\n  `).join(""))}function renderDestinations(){const a=document.getElementById("heritage-container");a&&(a.innerHTML=destinations.map(a=>`\n    <div class="card">\n      <i class="fa-solid fa-monument icon-feature"></i>\n      <h3>${a.region}</h3>\n      <p style="margin-bottom: 10px; color: var(--deccan-gold);"><strong>${a.attraction}</strong></p>\n      <p style="font-size: 0.95rem;">${a.description}</p>\n    </div>\n  `).join(""))}document.addEventListener("DOMContentLoaded",()=>{renderRoutes(),renderDestinations()});